export interface CodeProps extends ComponentPropsWithoutRef<'figure'> {
  code?: string
  copy?: boolean
  highlighted?: boolean
  label?: ReactNode
  language?: string
  theme?: CodeTheme
  variant?: CodeVariant
  wrap?: boolean
}

export const Code = ({
  children,
  className,
  code,
  copy = false,
  highlighted = false,
  label,
  language,
  theme = 'auto',
  variant = 'inline',
  wrap = false,
  ...props
}: CodeProps) => {
  const codeChildren = renderCodeChildren(code, children, language)

  if (variant === 'block') {
    return (
      <figure
        className={composeClassName('ui-code ui-code--block', wrap && 'ui-code--wrap', className)}
        data-code-theme={theme}
        data-language={language}
        data-ui-code
        {...props}
      >
        {renderCodeHeader({ copy, label, language })}
        {highlighted ? children : <pre><code>{codeChildren}</code></pre>}
      </figure>
    )
  }

  return (
    <code
      className={composeClassName('ui-code ui-code--inline', className)}
      data-code-theme={theme}
      data-language={language}
      {...props}
    >
      {code ?? children}
    </code>
  )
}

