const { classList, passthrough } = resolveLumenAstroProps(rest, [
  'ui-icon',
  size === 'sm' && 'ui-icon--sm',
  size === 'lg' && 'ui-icon--lg',
  size === 'xl' && 'ui-icon--xl'
], classProp, className)
