    {segments.map(index => (
      <button
        aria-hidden="true"
        class="ui-input-otp__segment"
        data-index={index}
        data-ui-input-otp-segment
        disabled={disabled}
        tabindex="-1"
        type="button"
      >
        <span data-ui-input-otp-char>&nbsp;</span>
      </button>
    ))}
  </div>
