            {option.label}
          </option>
        ))}
      </select>
      <input
        autoComplete="tel"
        className={composeClassName('ui-input ui-phone-input__number', inputClass)}
        defaultValue={defaultValue}
        inputMode="tel"
        name={name}
        placeholder={placeholder}
        type="tel"
      />
    </div>
  )
}

