import { composeClassName } from '@santi020k/lumen-core'
import Icon from './Icon.astro'

export interface Props extends HTMLAttributes<'div'> {
  value?: number
  max?: number
  readonly?: boolean
}

const {
  class: className,
  value = 0,
  max = 5,
  readonly = false,
  ...props
} = Astro.props

